// ✅ Pass Output<T> directly. Pulumi handles dependency tracking. No await/pulumi.output().
const dbSubnetGroup = new aws.rds.SubnetGroup("app-db-subnets", {
    subnetIds: cluster.core.subnetIds,
});

const db = new aws.rds.Instance("app-db", {
    engine: "postgres",
    engineVersion: "14.7",
    instanceClass: env === "prod" ? "db.t3.medium" : "db.t3.micro",
    allocatedStorage: 20,
    dbSubnetGroupName: dbSubnetGroup.name,
    vpcSecurityGroupIds: [cluster.instanceSecurityGroups[0]],
    username: "admin",
    password: dbPassword, // Output<string> accepted directly
    backupRetentionPeriod: 7,
    deletionProtection: true,
    publiclyAccessible: false,
    storageEncrypted: env === "prod",
    multiAz: env === "prod",
});

// 4. IAM Service Account
const serviceRole = new aws.iam.Role("app-service-role", {
    assumeRolePolicy: env === "prod"
        ? JSON.stringify({
            Version: "2012-10-17",
            Statement: [{
                Effect: "Allow",
                Action: "sts:AssumeRoleWithWebIdentity",
                Principal: { Federated: `arn:aws:iam::${pulumi.getStack()}:oidc-provider/*` },
                Condition: { StringEquals: { "sub": "system:serviceaccount:default:app" } },
            }],
        })
        : JSON.stringify({
            Version: "2012-10-17",
            Statement: [{
                Effect: "Allow",
                Action: "sts:AssumeRole",
                Principal: { AWS: `arn:aws:iam::${pulumi.getStack()}:user/app-dev` },
            }],
        }),
    inlinePolicies: [{
        name: "app-policy",
        policy: pulumi.interpolate`{
            "Version": "2012-10-17",
            "Statement": [{
                "Effect": "Allow",
                "Action": "${env === "prod" ? ["s3:GetObject", "s3:PutObject"] : ["s3:*"]}",
                "Resource": ["${bucket.arn}", "${bucket.arn}/*"]
            }]
        }`,
    }],
});

