if (env === "prod") {
    // CloudFront + ACM
    const cert = new aws.acm.Certificate("app-cert", {
        domainName: "app.example.com",
        validationMethod: "DNS",
    });

    const cf = new aws.cloudfront.Distribution("app-cf", {
        viewerCertificate: { acmCertificateArn: cert.arn },
        defaultCacheBehavior: { viewerProtocolPolicy: "https-only" },
        restrictions: { geoRestriction: { restrictionType: "none" } },
    });

    httpsEndpoint = cf.domainName;
